    cases = [(True, False), (False, False), (False, True), (True, False)]
    out = []
    for label, reward in cases:
        kind = '강화' if reward else ('지도' if label else '비지도')
        if not reward:
            out.append('O' if label else 'X')
        out.append(kind)
    return out

